/* Reproductor de WAV (PCM de 8 o 16 bits, cualquier frecuencia) */
#include "z.h"
static zwin *W; static char path[256], card[64], st[80]; static u8 *D; static long pcm, plen, pos; static int rate, ch, bits, playing, vol = 80, has;
static void load(const char *p) { strncpy0(path, p, 256); free(D); D = 0; playing = 0; pos = 0; long n; u8 *d = z_readfile(p, &n); strcpy(st, _("Formato no valido")); if (!d) { strcpy(st, _("No se puede abrir")); return; } if (n < 44 || memcmp(d, "RIFF", 4) || memcmp(d + 8, "WAVE", 4)) { free(d); return; } long o = 12; pcm = 0; while (o + 8 <= n) { u32 l = *(u32 *)(d + o + 4); if (!memcmp(d + o, "fmt ", 4)) { ch = *(u16 *)(d + o + 10); rate = *(u32 *)(d + o + 12); bits = *(u16 *)(d + o + 22); if (*(u16 *)(d + o + 8) != 1 && *(u16 *)(d + o + 8) != 0xFFFE) { free(d); return; } } else if (!memcmp(d + o, "data", 4)) { pcm = o + 8; plen = MIN((long)l, n - pcm); break; } o += 8 + l + (l & 1); } if (!pcm || !rate || (bits != 8 && bits != 16) || ch < 1 || ch > 2) { free(d); return; } D = d; snprintf(st, 80, _("%d Hz, %d bits, %s, %ld s"), rate, bits, ch == 2 ? _("estereo") : "mono", plen / (rate * ch * bits / 8)); }
static void draw(void) { g_grad(W, 0, 0, W->w, W->h, 0x1F2937, 0x111827); const char *n = strrchr(path, '/'); g_textb(W, 16, 14, n ? n + 1 : "Sin archivo", 0xFFFFFF); g_text(W, 16, 34, st, 0x9CA3AF); g_text(W, 16, 54, card, 0x5EEAD4); g_rect(W, 16, 80, W->w - 32, 8, 0x374151); if (D && plen) g_rect(W, 16, 80, (W->w - 32) * (pos / 1024) / MAX(1, plen / 1024), 8, 0x14B8A6); ui_button(W, 16, 102, 90, 30, playing ? "Pausa" : "Tocar", 2); ui_button(W, 112, 102, 70, 30, "Parar", 0); ui_button(W, 188, 102, 70, 30, "Abrir", 0); ui_button(W, 280, 102, 34, 30, "-", 0); ui_button(W, 318, 102, 34, 30, "+", 0); char v[16]; snprintf(v, 16, "%d%%", vol); g_text(W, 360, 110, v, 0xFFFFFF); zw_present(W); }
static void feed(void) { static short o[4096]; int fs = ch * bits / 8, frames = 0; long step = ((long)rate << 16) / 48000; static long fr; while (frames < 2048 && pos + fs <= plen) { const u8 *s = D + pcm + pos; int l, r; if (bits == 16) { l = ((short *)s)[0]; r = ch == 2 ? ((short *)s)[1] : l; } else { l = (s[0] - 128) << 8; r = ch == 2 ? (s[1] - 128) << 8 : l; } o[frames * 2] = l; o[frames * 2 + 1] = r; frames++; fr += step; pos += (fr >> 16) * fs; fr &= 0xFFFF; } if (frames) z_audio(o, frames * 4); if (pos + fs > plen) { playing = 0; pos = 0; z_log("[prueba] reproduccion terminada"); } }
int main(const char *a) {
    W = zw_new("Musica", -1, 0, 420, 150, WF_DECOR); has = z_audio_info(card, 64); vol = z_audio_vol(-1); load(a[0] ? a : "/rd/res/tono.wav"); draw(); zevent e; u64 t = 0;
    for (;;) { int g = z_event(&e, playing ? 5 : -1); if (g) { if (e.type == EV_REDRAW) { draw(); continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_DOWN && e.y >= 102 && e.y < 132) { if (e.x < 106) { if (D && has) playing = !playing; } else if (e.x < 182) { playing = 0; pos = 0; } else if (e.x < 258) { char n[256]; strcpy(n, path); if (ui_prompt("Abrir sonido", "Ruta del WAV:", n, 240)) load(n); } else if (e.x >= 280 && e.x < 314) z_audio_vol(vol = MAX(0, vol - 10)); else if (e.x >= 318 && e.x < 352) z_audio_vol(vol = MIN(100, vol + 10)); draw(); } else if (e.type == EV_KEY && e.ch == ' ') { if (D && has) playing = !playing; draw(); } }
        if (playing && z_audio_space() > 16384) feed(); if (playing && z_ms() - t > 250) { t = z_ms(); draw(); } }
}
